<?php if($staff): ?>
<nav class="order-tabs" aria-label="Bandejas de pedidos"><?php foreach($buckets as $key=>$info): ?><a href="<?= app_url_html('/admin/orders?bucket='.$key) ?>" <?= $bucket===$key?'aria-current="page"':'' ?>><?= $e($info[0]) ?><span><?= $counts[$key] ?></span></a><?php endforeach; ?></nav>
<section class="admin-table-panel orders-panel"><form class="catalog-filters orders-filters"><input type="hidden" name="bucket" value="<?= $e($bucket) ?>"><label>Buscar pedido<input name="q" type="search" maxlength="150" placeholder="Código o contacto"></label><label>Avance<select name="status"><option value="">Todos en esta bandeja</option><?php foreach($buckets[$bucket][1] as $state): ?><option value="<?= $state ?>" <?= ($_GET['status']??'')===$state?'selected':'' ?>><?= OrderModel::LABELS[$state] ?></option><?php endforeach; ?></select></label><button type="submit">Filtrar</button><button type="reset">Limpiar</button></form>
<div class="table-responsive"><table class="admin-table" data-admin-datatable aria-label="Pedidos de la tienda" data-table-kind="orders" data-table-url="<?= app_url_html('/orders/data?scope=admin') ?>"><thead><tr><th>Pedido</th><th>Contacto</th><th>Fechas</th><th>Total</th><th>Preparación y cobro</th><th>Detalle</th></tr></thead><tbody></tbody></table></div></section>
<?php else: ?>
<nav class="order-tabs" aria-label="Filtrar mis pedidos"><?php foreach(['all'=>'Todos','active'=>'En curso','closed'=>'Finalizados'] as $key=>$label): ?><a href="<?= app_url_html('/orders?filter='.$key) ?>" <?= $cards['filter']===$key?'aria-current="page"':'' ?>><?= $label ?></a><?php endforeach; ?></nav>
<?php if(!$cards['items']): ?><section class="orders-panel order-empty"><i class="bi bi-bag" aria-hidden="true"></i><h2><?= $cards['filter']==='all'?'Todavía no tienes pedidos':'No hay pedidos en este grupo' ?></h2><p>Los pedidos que confirmes aparecerán aquí.</p><a class="order-primary" href="<?= app_url_html('/store') ?>">Ver catálogo</a></section><?php else: ?>
<div class="customer-order-grid"><?php foreach($cards['items'] as $card): ?><article class="orders-panel customer-order-card"><header><div><small><?= $date($card['created_at']) ?></small><h2><?= $e($card['codigo_pedido']) ?></h2></div><span class="order-state order-state--<?= $e($card['estado']) ?>"><?= OrderModel::LABELS[$card['estado']] ?></span></header><p class="customer-order-products"><?= $e($card['products']) ?></p><?php if($card['reserva_activa']): ?><p class="customer-order-expiry"><i class="bi bi-clock" aria-hidden="true"></i> Retiro hasta <?= $date($card['fecha_vencimiento']) ?></p><?php endif; ?><footer><strong>$<?= $e($card['total']) ?></strong><a class="order-primary" href="<?= app_url_html('/orders/detail?id='.(int)$card['id_pedido']) ?>">Ver pedido <i class="bi bi-arrow-right" aria-hidden="true"></i></a><?php if(in_array($card['estado'],['pendiente','confirmado'],true)): ?><a class="customer-order-cancel" href="<?= app_url_html('/orders/detail?id='.(int)$card['id_pedido'].'#cancel') ?>">Cancelar pedido</a><?php endif; ?></footer></article><?php endforeach; ?></div>
<nav class="order-pagination" aria-label="Páginas de mis pedidos"><?php if($cards['page']>1): ?><a class="order-secondary" rel="prev" href="<?= app_url_html('/orders?filter='.$cards['filter'].'&page='.($cards['page']-1)) ?>">Anterior</a><?php endif; ?><span>Página <?= $cards['page'] ?> de <?= $cards['pages'] ?> · <?= $cards['total'] ?> pedidos</span><?php if($cards['page']<$cards['pages']): ?><a class="order-secondary" rel="next" href="<?= app_url_html('/orders?filter='.$cards['filter'].'&page='.($cards['page']+1)) ?>">Siguiente</a><?php endif; ?></nav>
<?php endif;endif; ?>
